script:
special_project = {
	key = "CARAVAN_HULK_PROJECT"
	days_to_research = 180
	tech_department = engineering_technology
	timelimit = 3600
	picture = GFX_evt_unknown_ships
	icon = "gfx/interface/icons/situation_log/situation_log_quest.dds"

	event_scope = ship_event

	triggered_requirement = {
		text = CONSTRUCTOR_PROJECT_REQUIREMENTS
		count = 1
		trigger = {
			OR = {
				is_ship_class = shipclass_constructor
				is_arkship_fleet = yes
			}
		}
	}

	on_success = {
		owner = { country_event = { id = cara.4025 } }
	}

	on_fail = {
		if = {
			limit = { exists = event_target:caravan_hulk_object }
			event_target:caravan_hulk_object = {
				destroy_ambient_object = this
			}
		}
	}
}
